-- Generated by `npm run db:seed` from db/generate-strokes.js.
-- Re-running the generator replaces this file deterministically.
begin;
on conflict (symbol) do update set phoneme_ipa = excluded.phoneme_ipa, phoneme_hint = excluded.phoneme_hint, tts_syllable = excluded.tts_syllable, category = excluded.category, is_lookalike = excluded.is_lookalike, similar_to = excluded.similar_to, difficulty = excluded.difficulty, example_words = excluded.example_words, tips = excluded.tips, writing_steps = excluded.writing_steps, strokes = excluded.strokes, sort_order = excluded.sort_order;

on conflict (id) do update set name = excluded.name, description = excluded.description, how_to_play = excluded.how_to_play, icon_key = excluded.icon_key, is_active = excluded.is_active, sort_order = excluded.sort_order;

on conflict (word) do update set syllables = excluded.syllables, emoji = excluded.emoji, sort_order = excluded.sort_order;
commit;
